/**
 * Rewrites Interview Coach's templated technical prompts into natural
 * interview questions — generated by AI, reviewed by a person, then applied.
 * Decision logic lives in lib/interview/questionRewrites.ts (unit-tested).
 *
 *   generate   Drafts a rewrite for every still-templated technical question
 *              and writes a REVIEW FILE. Reads the DB, writes nothing to it.
 *   apply      Applies the approved entries of the review file. Run with
 *              --dry-run first. Needs migration 0021 (template_prompt_text).
 *   rollback   Restores the original template wording for every rewritten
 *              question (uses template_prompt_text).
 *
 * Review file: interview-coach-main/review/question-rewrites.json
 * (interview-coach-main/ is git-ignored, so drafts never reach the repo).
 * While reviewing: edit "proposedText" freely; set "status" to "rejected"
 * to skip an entry. Entries carrying a "warning" failed validation and will
 * be skipped unless you fix "proposedText".
 *
 * Applying clears each rewritten question's prompt audio (it would read the
 * old wording). Afterwards, open Module Builder → Interview Coach and click
 * "Generate audio" so the server records the new wording.
 *
 * Usage:
 *   npx tsx -r dotenv/config scripts/rewrite-interview-coach-questions.ts generate dotenv_config_path=.env.local
 *   npx tsx -r dotenv/config scripts/rewrite-interview-coach-questions.ts apply --dry-run dotenv_config_path=.env.local
 *   npx tsx -r dotenv/config scripts/rewrite-interview-coach-questions.ts apply dotenv_config_path=.env.local
 * Options: --model <name> (generate; default gpt-4o), --force (generate;
 * overwrite an existing review file).
 */

import { and, eq, isNotNull, sql } from "drizzle-orm";
import fs from "node:fs";
import path from "node:path";
import { OpenAI } from "openai";
import { db } from "../DB/drizzle";
import {
  interviewModuleQuestionAssignments,
  interviewModules,
  interviewQuestionBank,
} from "../DB/interviewSchema";
import { classifySourceId } from "../lib/interview/questionTypes";
import {
  buildRewriteUserMessage,
  isTemplatedPrompt,
  planRewriteUpdates,
  REWRITE_SYSTEM_PROMPT,
  validateProposedQuestion,
  type RewriteReviewEntry,
} from "../lib/interview/questionRewrites";

const MODULE_NAME = "Interview Coach";
const ROOT = path.resolve(__dirname, "..");
const BANK_PATH = path.join(ROOT, "interview-coach-main", "data", "question_bank.json");
const REVIEW_PATH = path.join(ROOT, "interview-coach-main", "review", "question-rewrites.json");
const CONCURRENCY = 4;

interface BankTopic {
  id: string;
  topic: string;
  scenarios?: string[];
  answer_key?: { ideal_points?: string[] };
}
interface Bank {
  categories: { category: string; topics: BankTopic[] }[];
}

const args = process.argv.slice(2);
const command = args.find((a) => !a.startsWith("-") && !a.includes("="));
const flag = (name: string) => args.includes(`--${name}`);
const option = (name: string) => {
  const index = args.indexOf(`--${name}`);
  return index >= 0 ? args[index + 1] : undefined;
};

async function findModuleId(): Promise<string> {
  const [row] = await db
    .select({ id: interviewModules.id })
    .from(interviewModules)
    .where(eq(interviewModules.name, MODULE_NAME))
    .limit(1);
  if (!row) throw new Error(`Module "${MODULE_NAME}" not found.`);
  return row.id;
}

async function moduleQuestions(moduleId: string) {
  return db
    .select({
      id: interviewQuestionBank.id,
      promptText: interviewQuestionBank.promptText,
      sourceId: interviewQuestionBank.sourceId,
    })
    .from(interviewModuleQuestionAssignments)
    .innerJoin(
      interviewQuestionBank,
      eq(interviewQuestionBank.id, interviewModuleQuestionAssignments.questionId),
    )
    .where(eq(interviewModuleQuestionAssignments.moduleId, moduleId));
}

/** Runs fn over items with bounded parallelism, preserving order. */
async function mapLimited<T, R>(
  items: T[],
  limit: number,
  fn: (item: T, index: number) => Promise<R>,
): Promise<R[]> {
  const results: R[] = new Array(items.length);
  let next = 0;
  await Promise.all(
    Array.from({ length: Math.min(limit, items.length) }, async () => {
      while (next < items.length) {
        const index = next++;
        results[index] = await fn(items[index], index);
      }
    }),
  );
  return results;
}

async function generate() {
  if (fs.existsSync(REVIEW_PATH) && !flag("force")) {
    throw new Error(
      `${path.relative(ROOT, REVIEW_PATH)} already exists — it may contain review edits. ` +
        "Apply or delete it first, or pass --force to overwrite.",
    );
  }
  if (!process.env.OPENAI_API_KEY) throw new Error("OPENAI_API_KEY is not set.");
  const model = option("model") ?? process.env.REWRITE_MODEL ?? "gpt-4o";
  const client = new OpenAI({ apiKey: process.env.OPENAI_API_KEY });

  const bank: Bank = JSON.parse(fs.readFileSync(BANK_PATH, "utf-8"));
  const topics = new Map<string, BankTopic & { category: string }>();
  for (const category of bank.categories) {
    for (const topic of category.topics) {
      topics.set(topic.id, { ...topic, category: category.category });
    }
  }

  const moduleId = await findModuleId();
  const targets = (await moduleQuestions(moduleId)).filter(
    (q) =>
      q.sourceId &&
      classifySourceId(q.sourceId)?.questionType === "technical" &&
      isTemplatedPrompt(q.promptText),
  );
  console.log(`[rewrite] ${targets.length} templated technical questions. Model: ${model}`);

  let done = 0;
  const entries = await mapLimited(targets, CONCURRENCY, async (question) => {
    const topic = topics.get(question.sourceId!);
    const classification = classifySourceId(question.sourceId)!;
    const base: Omit<RewriteReviewEntry, "proposedText" | "scenarioUsed"> = {
      questionId: question.id,
      sourceId: question.sourceId!,
      category: classification.category,
      topic: topic?.topic ?? question.sourceId!,
      currentText: question.promptText,
      status: "approved",
    };

    let proposedText = "";
    let scenarioUsed = "";
    let warning: string | undefined;
    try {
      const response = await client.chat.completions.create({
        model,
        temperature: 0.6,
        response_format: { type: "json_object" },
        messages: [
          { role: "system", content: REWRITE_SYSTEM_PROMPT },
          {
            role: "user",
            content: buildRewriteUserMessage({
              topic: topic?.topic ?? question.sourceId!,
              category: classification.category,
              scenarios: topic?.scenarios ?? [],
              idealPoints: topic?.answer_key?.ideal_points ?? [],
            }),
          },
        ],
      });
      const parsed = JSON.parse(response.choices[0]?.message?.content ?? "{}");
      proposedText = String(parsed.question ?? "").trim();
      scenarioUsed = String(parsed.scenario_used ?? "").trim();
      warning = validateProposedQuestion(proposedText) ?? undefined;
    } catch (error) {
      warning = `generation failed: ${error instanceof Error ? error.message : String(error)}`;
    }

    done += 1;
    if (done % 10 === 0 || done === targets.length) {
      console.log(`[rewrite] ${done}/${targets.length}`);
    }
    return { ...base, proposedText, scenarioUsed, ...(warning ? { warning } : {}) };
  });

  fs.mkdirSync(path.dirname(REVIEW_PATH), { recursive: true });
  fs.writeFileSync(REVIEW_PATH, JSON.stringify(entries, null, 2) + "\n");
  const warned = entries.filter((e) => e.warning).length;
  console.log(
    `[rewrite] Wrote ${entries.length} drafts to ${path.relative(ROOT, REVIEW_PATH)}` +
      (warned ? ` (${warned} with warnings — fix or reject them).` : "."),
  );
  console.log("[rewrite] Review it, then run: apply --dry-run, then apply.");
}

async function apply() {
  const dryRun = flag("dry-run");
  if (!fs.existsSync(REVIEW_PATH)) {
    throw new Error(`No review file at ${path.relative(ROOT, REVIEW_PATH)} — run generate first.`);
  }
  const entries: RewriteReviewEntry[] = JSON.parse(fs.readFileSync(REVIEW_PATH, "utf-8"));
  const moduleId = await findModuleId();
  const { updates, skipped } = planRewriteUpdates(entries, await moduleQuestions(moduleId));

  for (const s of skipped) console.log(`  skip ${s.questionId}: ${s.reason}`);
  for (const u of updates.slice(0, dryRun ? updates.length : 5)) {
    console.log(`  ${u.questionId}\n    - ${u.from}\n    + ${u.to}`);
  }
  console.log(`[rewrite] ${updates.length} to apply, ${skipped.length} skipped.`);
  if (dryRun) {
    console.log("[rewrite] Dry run — nothing written.");
    return;
  }

  for (const u of updates) {
    await db
      .update(interviewQuestionBank)
      .set({
        promptText: u.to,
        promptTranscript: u.to,
        // Keep the ORIGINAL template even if a question is rewritten twice.
        templatePromptText: sql`COALESCE(${interviewQuestionBank.templatePromptText}, ${u.from})`,
        // The recorded audio reads the old wording — clear it so the
        // "Generate audio" job re-records it on the server.
        promptAudioPath: null,
      })
      .where(eq(interviewQuestionBank.id, u.questionId));
  }
  console.log(
    `[rewrite] Applied ${updates.length}. Next: Module Builder → ${MODULE_NAME} → "Generate audio".`,
  );
}

async function rollback() {
  const dryRun = flag("dry-run");
  const moduleId = await findModuleId();
  const rows = await db
    .select({
      id: interviewQuestionBank.id,
      promptText: interviewQuestionBank.promptText,
      templatePromptText: interviewQuestionBank.templatePromptText,
    })
    .from(interviewModuleQuestionAssignments)
    .innerJoin(
      interviewQuestionBank,
      eq(interviewQuestionBank.id, interviewModuleQuestionAssignments.questionId),
    )
    .where(
      and(
        eq(interviewModuleQuestionAssignments.moduleId, moduleId),
        isNotNull(interviewQuestionBank.templatePromptText),
      ),
    );

  console.log(`[rewrite] ${rows.length} rewritten questions to restore.`);
  if (dryRun) return;
  for (const row of rows) {
    await db
      .update(interviewQuestionBank)
      .set({
        promptText: row.templatePromptText!,
        promptTranscript: row.templatePromptText!,
        templatePromptText: null,
        promptAudioPath: null,
      })
      .where(eq(interviewQuestionBank.id, row.id));
  }
  console.log(`[rewrite] Restored ${rows.length}. Regenerate audio in the Module Builder.`);
}

async function main() {
  if (command === "generate") await generate();
  else if (command === "apply") await apply();
  else if (command === "rollback") await rollback();
  else {
    console.log("Usage: rewrite-interview-coach-questions.ts <generate|apply|rollback> [--dry-run] [--model <name>] [--force]");
    process.exit(1);
  }
  process.exit(0);
}

main().catch((error) => {
  console.error("[rewrite] Fatal:", error instanceof Error ? error.message : error);
  process.exit(1);
});
